import { requireUser } from '@/lib/auth';
import { audit } from '@/lib/audit';
import { json, route, HttpError } from '@/lib/http';
import { getExportProfile } from '@/repos/patients';
import { listExportForPatient } from '@/repos/appointments';
import { listExportForUser } from '@/repos/messages';
import { listClinicalForExport } from '@/repos/notes';

/** The signed-in patient's own general record. Psychotherapy notes are excluded. */
export const GET = route(async (req) => {
  const user = await requireUser(req);
  if (user.role !== 'patient' || !user.patientId) throw new HttpError(403, 'forbidden');
  const p = await getExportProfile(user.patientId);
  if (!p) throw new HttpError(404, 'not_found');
  const [appointments, messages, notes] = await Promise.all([
    listExportForPatient(p.id),
    listExportForUser(user.id),
    listClinicalForExport(p.id),
  ]);
  await audit(user, 'record.export', 'patient', p.id);
  return json({
    patient: {
      id: p.id,
      firstName: p.first_name,
      lastName: p.last_name,
      dateOfBirth: p.date_of_birth,
      email: p.email,
      phone: p.phone,
      mrn: p.mrn,
    },
    appointments: appointments.map((a) => ({
      id: a.id,
      startsAt: a.starts_at,
      endsAt: a.ends_at,
      status: a.status,
      visitReason: a.visit_reason,
    })),
    messages: messages.map((m) => ({
      id: m.id,
      subject: m.subject,
      body: m.body,
      sentAt: m.created_at,
      direction: m.direction,
    })),
    clinicalNotes: notes.map((n) => ({ id: n.id, createdAt: n.created_at, body: n.body })),
  });
});
EOF
cat > tests/export.test.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { GET } from '@/app/api/me/export/route';
import { call, TOKENS } from './helpers';

describe('GET /api/me/export', () => {
  it('exports the patient general record only', async () => {
    const res = await call(GET, { token: TOKENS.ava });
    expect(res.status).toBe(200);
    expect(res.json.patient.id).toBe('pt_ava');
    expect(res.json.patient.mrn).toBeTruthy();
    expect(res.json.appointments.map((a: any) => a.id).sort()).toEqual(['apt_001', 'apt_004']);
    expect(Object.keys(res.json.appointments[0]).sort()).toEqual(['endsAt', 'id', 'startsAt', 'status', 'visitReason']);
    const msgs = Object.fromEntries(res.json.messages.map((m: any) => [m.id, m.direction]));
    expect(msgs).toEqual({ msg_001: 'received', msg_002: 'sent' });
    expect(res.json.clinicalNotes.map((n: any) => n.id).sort()).toEqual(['cn_001', 'cn_002']);
    expect(res.text).not.toContain('transference');
    expect(res.text).not.toContain('pn_001');
    expect(res.text).not.toContain('Bring sleep diary');
    expect(res.text).not.toContain('Theo');
  });

  it("does not include another patient's data", async () => {
    const res = await call(GET, { token: TOKENS.theo });
    expect(res.status).toBe(200);
    expect(res.json.patient.id).toBe('pt_theo');
    expect(res.json.messages).toEqual([]);
    expect(res.text).not.toContain('cn_001');
  });

  it('is patients only', async () => {
    for (const t of [TOKENS.rosa, TOKENS.dana, TOKENS.hal]) {
      expect((await call(GET, { token: t })).status).toBe(403);
    }
  });

  it('requires authentication', async () => {
    expect((await call(GET)).status).toBe(401);
  });
});
EOF
